-- Translation drift notes: short editorial notes on Hebrew/Greek words
-- whose usual English rendering has drifted from, narrowed, or merged the
-- original sense. Kept apart from strongs_entries, which the original-
-- language import truncates and reloads.

create table public.strongs_drift_notes (
  number text primary key,
  note text not null,
  updated_at timestamptz not null default now(),

  constraint strongs_drift_notes_number_format check (number ~ '^[GH][0-9]{4}$'),
  constraint strongs_drift_notes_note_length check (
    char_length(note) <= 900 and note ~ '\S'
  )
);

alter table public.strongs_drift_notes enable row level security;

grant select on public.strongs_drift_notes to anon, authenticated;
grant all on public.strongs_drift_notes to service_role;

create policy "Anyone can read drift notes"
on public.strongs_drift_notes for select to anon, authenticated using (true);

comment on table public.strongs_drift_notes is 'Editorial notes on how English renderings differ from the original word (Dawnscroll content).';

on conflict (number) do update set note = excluded.note, updated_at = now();
